using System.Collections.Generic;
using RimWorld;
using UnityEngine;
using Verse;
using Verse.Grammar;
using Verse.Sound;

namespace Dominion
{
    /// <summary>
    /// Dominion's paper-and-ink look (design §6): newsprint, ink colours, rubber stamps, ornamental rules and category
    /// pictograms, all generated by tools/textures/make_ui.py. Text drawn on paper must use the ink colours, never white.
    /// </summary>
    [StaticConstructorOnStartup]
    public static class DominionTheme
    {
        public static readonly Texture2D Paper = Tex("Paper");
        public static readonly Texture2D Masthead = Tex("Masthead");
        public static readonly Texture2D Title = Tex("Title");
        public static readonly Texture2D Rule = Tex("Rule");
        public static readonly Texture2D Seal = Tex("Seal");
        public static readonly Texture2D Pin = Tex("Pin");
        public static readonly Texture2D StampConfirmed = Tex("Stamp_Confirmed");
        public static readonly Texture2D StampRumor = Tex("Stamp_Rumor");
        public static readonly Texture2D StampDisproved = Tex("Stamp_Disproved");
        public static readonly Texture2D StampStopPress = Tex("Stamp_StopPress");
        public static readonly Texture2D StampClassified = Tex("Stamp_Classified");
        public static readonly Texture2D StampInvestigate = Tex("Stamp_Investigate");
        public static readonly Texture2D StampInquiry = Tex("Stamp_Inquiry");
        public static readonly Texture2D StampVerified = Tex("Stamp_Verified");
        public static readonly Texture2D StampAdvisory = Tex("Stamp_Advisory");
        public static readonly Texture2D StampInForce = Tex("Stamp_InForce");
        public static readonly Texture2D StampQueued = Tex("Stamp_Queued");
        public static readonly Texture2D GizmoAdvisory = Tex("Gizmo_Advisory");
        public static readonly Texture2D GizmoInvestigate = Tex("Gizmo_Investigate");

        private static readonly Dictionary<EventCategory, Texture2D> categoryIcons = new Dictionary<EventCategory, Texture2D>();

        public static readonly Color Ink = new Color(0.18f, 0.15f, 0.12f);
        public static readonly Color InkFaded = new Color(0.36f, 0.31f, 0.25f);
        public static readonly Color InkRed = new Color(0.58f, 0.12f, 0.11f);
        public static readonly Color InkGreen = new Color(0.16f, 0.43f, 0.2f);
        public static readonly Color InkAmber = new Color(0.68f, 0.43f, 0.08f);
        public static readonly Color PaperShade = new Color(0.36f, 0.27f, 0.16f, 0.12f);
        public static readonly Color PaperHighlight = new Color(0.55f, 0.38f, 0.16f, 0.2f);

        static DominionTheme()
        {
            foreach (EventCategory c in System.Enum.GetValues(typeof(EventCategory)))
                categoryIcons[c] = ContentFinder<Texture2D>.Get("UI/Dominion/Cat_" + c, reportFailure: false) ?? ContentFinder<Texture2D>.Get("UI/Dominion/Cat_General");
        }

        private static Texture2D Tex(string name) => ContentFinder<Texture2D>.Get("UI/Dominion/" + name);

        public static Texture2D CategoryIcon(EventCategory c) => categoryIcons.TryGetValue(c, out Texture2D t) ? t : null;

        /// <summary>A sheet of newsprint with a thin dark edge.</summary>
        public static void DrawPaper(Rect rect)
        {
            GUI.color = Color.white;
            GUI.DrawTexture(rect, Paper, ScaleMode.StretchToFill);
            GUI.color = new Color(0.25f, 0.2f, 0.14f, 0.8f);
            Widgets.DrawBox(rect);
            GUI.color = Color.white;
        }

        /// <summary>An ink drawing (white texture) tinted in <paramref name="color"/>.</summary>
        public static void DrawInk(Rect rect, Texture2D tex, Color color, ScaleMode mode = ScaleMode.ScaleToFit)
        {
            Color old = GUI.color;
            GUI.color = color;
            GUI.DrawTexture(rect, tex, mode);
            GUI.color = old;
        }

        /// <summary>A rubber stamp, slightly crooked, as stamps are.</summary>
        public static void DrawStamp(Rect rect, Texture2D stamp, Color color, float angle)
        {
            Matrix4x4 m = GUI.matrix;
            UI.RotateAroundPivot(angle, rect.center);
            DrawInk(rect, stamp, new Color(color.r, color.g, color.b, 0.85f));
            GUI.matrix = m;
        }

        /// <summary>
        /// A rubber stamp the player can press: faint until hovered, then fully inked and pressed down a little.
        /// Returns true when clicked. A disabled stamp is drawn grey and shows <paramref name="disabledReason"/>.
        /// </summary>
        public static bool StampButton(Rect rect, Texture2D stamp, Color color, float angle, string tooltip, string disabledReason = null, bool lit = false)
        {
            bool disabled = disabledReason != null;
            bool over = !disabled && Mouse.IsOver(rect);
            Color ink = disabled ? new Color(0.45f, 0.42f, 0.38f) : color;
            float alpha = disabled ? 0.45f : over || lit ? 1f : 0.65f;
            Rect r = over && Input.GetMouseButton(0) ? rect.ContractedBy(2f) : rect;
            if (over) Widgets.DrawBoxSolid(rect.ExpandedBy(2f), PaperShade);
            Matrix4x4 m = GUI.matrix;
            UI.RotateAroundPivot(angle, r.center);
            DrawInk(r, stamp, new Color(ink.r, ink.g, ink.b, alpha));
            GUI.matrix = m;
            TooltipHandler.TipRegion(rect, disabled ? tooltip + "\n\n" + disabledReason.Colorize(ColorLibrary.RedReadable) : tooltip);
            if (disabled) return false;
            if (Widgets.ButtonInvisible(rect))
            {
                SoundDefOf.Click.PlayOneShotOnCamera();
                return true;
            }
            return false;
        }

        /// <summary>A label in ink.</summary>
        public static void InkLabel(Rect rect, string text, Color? color = null, GameFont font = GameFont.Small, TextAnchor anchor = TextAnchor.UpperLeft)
        {
            GameFont oldFont = Text.Font;
            TextAnchor oldAnchor = Text.Anchor;
            Color old = GUI.color;
            Text.Font = font;
            Text.Anchor = anchor;
            GUI.color = color ?? Ink;
            Widgets.Label(rect, text);
            GUI.color = old;
            Text.Font = oldFont;
            Text.Anchor = oldAnchor;
        }

        /// <summary>A centred ornamental rule (line, diamond, line).</summary>
        public static void DrawRule(Rect rect, Color? color = null) => DrawInk(rect, Rule, color ?? Ink, ScaleMode.StretchToFill);

        /// <summary>A section heading for listings on the dark window background: medium text and an ornamental rule.</summary>
        public static void Header(Listing_Standard l, string text)
        {
            l.Gap(6f);
            Text.Font = GameFont.Medium;
            Rect r = l.GetRect(Text.CalcHeight(text, l.ColumnWidth));
            GUI.color = new Color(0.95f, 0.85f, 0.6f);
            Widgets.Label(r, text);
            GUI.color = Color.white;
            Text.Font = GameFont.Small;
            Rect rule = l.GetRect(10f);
            DrawInk(new Rect(rule.x, rule.y, Mathf.Min(rule.width, 360f), rule.height), Rule, new Color(0.85f, 0.72f, 0.45f, 0.75f), ScaleMode.StretchToFill);
            l.Gap(2f);
        }

        // ------------------------------------------------------------------ flavour text

        private static readonly Dictionary<long, string> flavourCache = new Dictionary<long, string>();

        /// <summary>
        /// A line from the newspaper's flavour grammar (Dominion_NewsFlavor): reporters, mottos, classified ads.
        /// The same seed always gives the same line; results are cached.
        /// </summary>
        public static string Flavour(string root, int seed)
        {
            long key = ((long)root.GetHashCode() << 32) ^ (uint)seed;
            if (flavourCache.TryGetValue(key, out string s)) return s;
            s = "";
            RulePackDef pack = DefDatabase<RulePackDef>.GetNamedSilentFail("Dominion_NewsFlavor");
            if (pack != null)
            {
                Rand.PushState(seed);
                try
                {
                    GrammarRequest req = default;
                    req.Includes.Add(pack);
                    s = GrammarResolver.Resolve(root, req, "Dominion flavour", false, null, null, null, true);
                }
                catch (System.Exception e)
                {
                    DLog.WarningOnce("Newspaper flavour failed: " + e.Message, 0x4E57);
                }
                finally
                {
                    Rand.PopState();
                }
            }
            if (flavourCache.Count > 2000) flavourCache.Clear();
            flavourCache[key] = s;
            return s;
        }

        /// <summary>Today's edition number: one paper a day since the colony was founded.</summary>
        public static int Edition => GenDate.DaysPassed + 1;

        /// <summary>The cover price follows Economics &amp; Demography's inflation when it is there.</summary>
        public static int Price
        {
            get
            {
                float inflation = IntegrationRegistry.Get<Integration_EconomicsDemography>()?.Inflation ?? 1f;
                return Mathf.Max(1, Mathf.RoundToInt(2f * inflation));
            }
        }

        public static string TodayLong()
        {
            Map map = Find.CurrentMap ?? Find.AnyPlayerHomeMap;
            Vector2 longLat = map != null ? Find.WorldGrid.LongLatOf(map.Tile) : Vector2.zero;
            return GenDate.DateFullStringAt(GenDate.TickGameToAbs(Find.TickManager.TicksGame), longLat);
        }

        public static string WeatherNow()
        {
            Map map = Find.CurrentMap ?? Find.AnyPlayerHomeMap;
            return map?.weatherManager?.curWeather?.label ?? "Dominion_News_WeatherUnknown".Translate().ToString();
        }
    }
}
